  mktSeries(seed, chg) {
    let s = Math.abs(Math.round(seed)) * 9301 + 49297;
    const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
    const n = 44, out = [];
    let v = 0;
    for (let i = 0; i < n; i++) {
      v += (rnd() - 0.47) * 1.6 + (chg / n) * 0.9;
      out.push(v);
    }
    const lo = Math.min(...out), hi = Math.max(...out), sp = (hi - lo) || 1;
    const W = 120, H = 38;
    const pts = out.map((y, i) => [(i / (n - 1)) * W, H - 3 - ((y - lo) / sp) * (H - 6)]);
    const line = pts.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ");
    return { line, area: line + " L" + W + " " + H + " L0 " + H + " Z" };
  }
  // A drawdown can never exceed 100%: compress negatives asymptotically.
  compressPct(v) { return v >= 0 ? v : +(-100 * (1 - 1 / (1 + Math.abs(v) / 110))).toFixed(2); }
  periodRet(rk) { return { "1D": 0.007, "1W": 0.021, "1M": 0.1232, "3M": 0.185, "1Y": 0.340, "5Y": 1.900, "10Y": 5.200 }[rk] || 0.007; }
  // Every panel reads off periodRet(): an instrument's period move is the market's
  // period return × its beta (its 1D move relative to the S&P's) × a small wobble.
  rangeChgOf(x, betaScale) {
    const rk = (this.state && this.state.range) || "1D";
    if (rk === "1D") return x.chg;
    const damp = /^(VIX|VIX9D|VVIX|MOVE|VX|US10Y|US02Y|DXY|EURUSD)$/.test(x.k || "") ? 0.085 : (betaScale || 0.45);
    const h = this.rhash(x.seed, rk);
    const wob = 0.86 + (h % 1000) / 1000 * 0.3;
    return this.compressPct(+(this.periodRet(rk) * 100 * (x.chg / 0.62) * damp * wob).toFixed(2));
  }
  mktRow(x) {
    const rk = (this.state && this.state.range) || "1D";
    const chgV = this.rangeChgOf(x);
    const absV = x.chg ? x.abs / x.chg * chgV : x.abs;
    const up = chgV >= 0;
    const sp = this.mktSeries(x.seed + this.rangeIdx(rk) * 17, chgV);
    const dec = x.dec == null ? 2 : x.dec;
    return {
      key: x.k, k: x.k, label: x.label, sub: x.sub,
      valStr: (x.pre || "") + x.val.toLocaleString("en-US", { minimumFractionDigits: dec, maximumFractionDigits: dec }) + (x.post || ""),
      chgStr: (up ? "+" : "−") + Math.abs(chgV).toFixed(2) + "%",
      absStr: (up ? "+" : "−") + Math.abs(absV).toLocaleString("en-US", { minimumFractionDigits: dec, maximumFractionDigits: dec }),
      col: up ? HPAL.up : HPAL.dn,
      tint: up ? "rgba(74,222,128,.13)" : "rgba(248,113,113,.13)",
      arrow: up ? "▲" : "▼",
      lineD: sp.line, areaD: sp.area,
    };
  }
